class Scalar:
    def __init__(self, data, _children=(), _op="", label=""):
        self.data = data
        self.grad = 0.0
        self._prev = set(_children)
        self._op = _op
        self.label = label
        self._backward = lambda: None

    def __add__(self, other):
        out = Scalar(self.data + other.data, (self, other), "+")
        def _backward():
            self.grad += out.grad
            other.grad += out.grad
        out._backward = _backward
        return out

    def __mul__(self, other):
        out = Scalar(self.data * other.data, (self, other), "*")
        def _backward():
            self.grad += other.data * out.grad
            other.grad += self.data * out.grad
        out._backward = _backward
        return out

    def __repr__(self):
        return f"Scalar(data={self.data}, grad={self.grad})"

    def _topological(self):
        topo = []
        visited = set()
        def visit(node):
            if node not in visited:
                visited.add(node)
                for child in node._prev:
                    visit(child)
                topo.append(node)
        visit(self)
        return topo

    def backward(self):
        topo = self._topological()
        self.grad = 1.0
        for node in reversed(topo):
            node._backward()

    def __pow__(self, exponent):
        assert isinstance(exponent, (int, float)), "Only int/float powers are supported"
        out = Scalar(self.data ** exponent, (self,), f"**{exponent}")
        def _backward():
            # x**0 is constant, including at x = 0.
            if exponent != 0:
                self.grad += exponent * self.data ** (exponent - 1) * out.grad
        out._backward = _backward
        return out

    def __neg__(self):
        return self * Scalar(-1.0)

    def __sub__(self, other):
        return self + (-other)

    def __truediv__(self, other):
        return self * other ** -1


a = Scalar(6.0)
b = Scalar(2.0)

c = a / b

assert c.data == 3.0

c.backward()

assert abs(a.grad - 0.5) &lt; 1e-10
assert abs(b.grad - (-1.5)) &lt; 1e-10

print("Division test passed!")

